def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"[A-Z][0-9]+|[A-Z]+|[0-9]+|<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }

    def parse(formula):
        tokens = token_pattern.findall(formula)
        operands = []
        operators = []
        expect_operand = True

        def apply_operator():
            op = operators.pop()
            if op == "neg":
                operands.append(("neg", operands.pop()))
            else:
                right = operands.pop()
                left = operands.pop()
                operands.append((op, left, right))

        for token in tokens:
            if token.isdigit():
                operands.append(("num", int(token)))
                expect_operand = False
            elif token[0].isalpha():
                if token in ("SUM", "MIN", "MAX", "IF"):
                    operators.append(("function", token))
                else:
                    operands.append(("ref", token))
                    expect_operand = False
            elif token == "(":
                is_function = bool(
                    operators
                    and isinstance(operators[-1], tuple)
                    and operators[-1][0] == "function"
                )
                operators.append(["(", 0, is_function])
                expect_operand = True
            elif token == ",":
                while not isinstance(operators[-1], list):
                    apply_operator()
                operators[-1][1] += 1
                expect_operand = True
            elif token == ")":
                while not isinstance(operators[-1], list):
                    apply_operator()
                marker = operators.pop()
                if marker[2]:
                    name = operators.pop()[1]
                    count = marker[1] + 1
                    args = operands[-count:]
                    del operands[-count:]
                    operands.append(("call", name, args))
                expect_operand = False
            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and isinstance(operators[-1], str):
                    top = operators[-1]
                    if precedence[top] > precedence[op] or (
                        precedence[top] == precedence[op] and op != "neg"
                    ):
                        apply_operator()
                    else:
                        break
                operators.append(op)
                expect_operand = True

        while operators:
            apply_operator()
        return operands[0]

    def arguments_in_order(args):
        for arg in args:
            if arg[0] != ":":
                yield arg
                continue

            first = arg[1][1]
            last = arg[2][1]
            col1, col2 = sorted((ord(first[0]), ord(last[0])))
            row1, row2 = sorted((int(first[1:]), int(last[1:])))
            for row in range(row1, row2 + 1):
                for col in range(col1, col2 + 1):
                    name = chr(col) + str(row)
                    if name in cells:
                        yield ("ref", name)

    values = {}
    in_progress = set()
    parsed = {}

    def evaluate(name):
        tasks = [("cell", name)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                cell = task[1]
                if cell not in cells:
                    results.append(0)
                elif cell in values:
                    results.append(values[cell])
                elif cell in in_progress:
                    results.append("#CYCLE!")
                else:
                    in_progress.add(cell)
                    content = cells[cell]
                    tasks.append(("finish_cell", cell))
                    if content.startswith("="):
                        if cell not in parsed:
                            parsed[cell] = parse(content[1:])
                        tasks.append(("eval", parsed[cell]))
                    else:
                        results.append(int(content))

            elif kind == "finish_cell":
                cell = task[1]
                values[cell] = results[-1]
                in_progress.remove(cell)

            elif kind == "eval":
                node = task[1]
                op = node[0]
                if op == "num":
                    results.append(node[1])
                elif op == "ref":
                    tasks.append(("cell", node[1]))
                elif op == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif op == "call":
                    function, args = node[1], node[2]
                    if function == "IF":
                        tasks.append(("if", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append((
                            "aggregate",
                            function,
                            iter(arguments_in_order(args)),
                            None,
                        ))
                else:
                    tasks.append(("binary_left", op, node[2]))
                    tasks.append(("eval", node[1]))

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                elif op == ">=":
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                function, iterator, accumulated = task[1:]
                node = next(iterator, None)
                if node is None:
                    results.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(("aggregate_value", function, iterator, accumulated))
                    tasks.append(("eval", node))

            elif kind == "aggregate_value":
                function, iterator, accumulated = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if accumulated is None:
                        accumulated = value
                    elif function == "SUM":
                        accumulated += value
                    elif function == "MIN":
                        accumulated = min(accumulated, value)
                    else:
                        accumulated = max(accumulated, value)
                    tasks.append(("aggregate", function, iterator, accumulated))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
